  "unusedUnits": [
    {
      "id": "AU-0010",
      "speaker": "Clara",
      "text": "Moment, ich dachte es geht um Rechnungsdownload?"
    },
    {
      "id": "AU-0017",
      "speaker": "Ben",
      "text": "Was sind die KPIs?"
    },
    {
      "id": "AU-0019",
      "speaker": "Clara",
      "text": "Zeit bis Angebot ist kein personenbezogenes Datum. Das ist gut."
    },
    {
      "id": "AU-0024",
      "speaker": "Anna",
      "text": "Ja Logging. Aber bitte nicht zu komplex. Wir haben keine Zeit."
    },
    {
      "id": "AU-0034",
      "speaker": "Clara",
      "text": "Genau."
    },
    {
      "id": "AU-0039",
      "speaker": "Anna",
      "text": "Komplexer hei\u00DFt mehr Zeit."
    },
    {
      "id": "AU-0040",
      "speaker": "Ben",
      "text": "Ja."
    },
    {
      "id": "AU-0042",
      "speaker": "Anna",
      "text": "Backup?"
    },
    {
      "id": "AU-0049",
      "speaker": "Ben",
      "text": "Das ist ein Unterschied."
    },
    {
      "id": "AU-0053",
      "speaker": "Anna",
      "text": "Wir drehen uns im Kreis."
    },
    {
      "id": "AU-0058",
      "speaker": "Anna",
      "text": "Ja. (Stille)"
